                    | SyntaxKind::CaretEqualsToken
                    | SyntaxKind::Identifier
                    | SyntaxKind::PrivateIdentifier
                    | SyntaxKind::JSDocCommentTextToken
                    | SyntaxKind::BreakKeyword
                    | SyntaxKind::CaseKeyword
                    | SyntaxKind::CatchKeyword
